# Code node: extract plaintext from Google Docs structure + build Retell pre-call response
EXTRACT_CODE = r"""
// Google Docs `get` returns body.content as an array of structural elements.
// Extract plaintext by walking paragraphs → elements → textRun.content
const doc = $input.first().json;
const body = doc.body || {};
const content = body.content || [];
const parts = [];
for (const el of content) {
  const para = el.paragraph;
  if (!para) continue;
  for (const pe of (para.elements || [])) {
    const tr = pe.textRun;
    if (tr && tr.content) parts.push(tr.content);
  }
}
const kb = parts.join('').trim();
// Retell pre-call webhook spec: respond with { call_inbound: { dynamic_variables: {...} } }
return [{
  json: {
    call_inbound: {
      dynamic_variables: {
        knowledge_base: kb
      }
    }
  }
}];
"""

