            "typeVersion": 2,
            "position": [460, 300],
            "credentials": {
                "googleDocsOAuth2Api": {
                    "id": "58qerrOCaSjZ51WF",
                    "name": "Google Docs account"
                }
            }
        },
        {
            "parameters": {
                "jsCode": EXTRACT_CODE
            },
            "id": "node-extract",
            "name": "Extract Text + Build Response",
            "type": "n8n-nodes-base.code",
            "typeVersion": 2,
            "position": [680, 300]
        },
        {
            "parameters": {
                "respondWith": "firstIncomingItem",
                "options": {}
            },
            "id": "node-respond",
            "name": "Respond to Webhook",
            "type": "n8n-nodes-base.respondToWebhook",
            "typeVersion": 1.1,
            "position": [900, 300]
        }
    ],
    "connections": {
        "Webhook": {
            "main": [[{"node": "Get KB", "type": "main", "index": 0}]]
        },
        "Get KB": {
            "main": [[{"node": "Extract Text + Build Response", "type": "main", "index": 0}]]
        },
