"""
import json, urllib.request, urllib.error

API_KEY = "eyJ.[REDACTED-JWT]"
BASE = "https://xprime17.app.n8n.cloud/api/v1"
WF_ID = "QFxDu1MBooL332PN"

RESOLVE_CODE = r"""
// Multicentre phone-to-Doc registry.
// Add a new centre by inserting an entry here. Same Doc can map to multiple phones
// (EG has two phones — direct dial + Bell-forward target — both share one Doc).
const PHONE_TO_CENTRE = {
  // East Gwillimbury
  '+12898038797': { centre_id: 'east-gwillimbury-on-ca', documentURL: 'https://docs.google.com/document/d/1QTvkO1d72KYIi2ALtPEIrOASsbxggxeyCRiS1rWK3Ek/edit' },
  '+12899030611': { centre_id: 'east-gwillimbury-on-ca', documentURL: 'https://docs.google.com/document/d/1QTvkO1d72KYIi2ALtPEIrOASsbxggxeyCRiS1rWK3Ek/edit' },
  // Pickering — add phone here once Retell inbound agent + forwarding is live
  // Leaside — add phone here once Retell inbound agent + forwarding is live
};

const payload = $input.first().json;
// Retell sends { event: "call_inbound", call_inbound: { agent_id, from_number, to_number } }
const body = payload.body || payload;
const inbound = body.call_inbound || {};
const toNumber = inbound.to_number || body.to_number;

if (!toNumber) {
  throw new Error(`Missing to_number in Retell payload. Got keys: ${Object.keys(body).join(', ')}`);
}

const centre = PHONE_TO_CENTRE[toNumber];
if (!centre) {
  throw new Error(`No KB mapping for inbound number ${toNumber}. Add entry to PHONE_TO_CENTRE in 'Resolve Centre' code node.`);
}

return [{ json: { to_number: toNumber, centre_id: centre.centre_id, documentURL: centre.documentURL } }];
"""

BUILD_RESPONSE_CODE = r"""
// n8n googleDocs .get returns {documentId, content} with plaintext in content.
const doc = $input.first().json;
const kb = (doc.content || '').trim();
if (!kb) {
  throw new Error(`Google Doc returned empty content for documentId=${doc.documentId}`);
}
return [{ json: { call_inbound: { dynamic_variables: { knowledge_base: kb } } } }];
