        "typeVersion": 2,
        "position": [600, 300],
        "credentials": {
            "googleDocsOAuth2Api": {
                "id": "58qerrOCaSjZ51WF",
                "name": "Google Docs account"
            }
        }
    },
    {
        "parameters": {"jsCode": BUILD_RESPONSE_CODE},
        "id": "node-build",
        "name": "Build Response",
        "type": "n8n-nodes-base.code",
