        "position": [960, 300]
    }
]

new_connections = {
    "Webhook": {"main": [[{"node": "Resolve Centre", "type": "main", "index": 0}]]},
    "Resolve Centre": {"main": [[{"node": "Get KB", "type": "main", "index": 0}]]},
    "Get KB": {"main": [[{"node": "Build Response", "type": "main", "index": 0}]]},
