"""Harden Multicentre KB workflow — fail-open on unknown numbers with a log marker
that surfaces in successful executions (searchable) rather than throwing.
"""
import json, urllib.request, urllib.error

API_KEY = "eyJ.[REDACTED-JWT]"
BASE = "https://xprime17.app.n8n.cloud/api/v1"
WF_ID = "QFxDu1MBooL332PN"

# Resolve: set kb_missing flag if unknown. Build Response handles both paths.
