  '+12899030611': { centre_id: 'east-gwillimbury-on-ca', documentURL: 'https://docs.google.com/document/d/1QTvkO1d72KYIi2ALtPEIrOASsbxggxeyCRiS1rWK3Ek/edit' },
  // Pickering — add phone here once Retell inbound agent + forwarding is live
  //   Doc URL: https://docs.google.com/document/d/1j3AX1R61Tz4-R_zTrCyGL--XBq2GMS9afuqFjrprmDY/edit
  // Leaside — add phone here once Retell inbound agent + forwarding is live
  //   Doc URL: https://docs.google.com/document/d/1hDmMP6565YUXbXu9srTpADGBhZy8xt4woODiqfsoSDI/edit
};

const payload = $input.first().json;
const body = payload.body || payload;
const inbound = body.call_inbound || {};
const toNumber = inbound.to_number || body.to_number || '';

const centre = PHONE_TO_CENTRE[toNumber];
if (!centre) {
  // Fail-open: return a marker so Build Response returns empty KB. Call proceeds
  // without context rather than failing. Search n8n executions for 'kb_missing=true'
  // to find misconfigured phones.
  return [{ json: {
    to_number: toNumber,
    centre_id: 'unknown',
    documentURL: '',
    kb_missing: true,
    warning: `No KB mapping for to_number='${toNumber}'. Add entry to PHONE_TO_CENTRE.`
  } }];
}
return [{ json: {
  to_number: toNumber,
  centre_id: centre.centre_id,
  documentURL: centre.documentURL,
  kb_missing: false
} }];
"""

# IF node: route known→Get KB, unknown→skip to Build Response with empty kb
# For simplicity, use Code-level fallback: always call Get KB with guard, Build handles both
BUILD_RESPONSE_CODE = r"""
// Two input shapes:
//   From Get KB (known centre): { documentId, content }
//   From Resolve Centre (unknown, skipped Get KB): { kb_missing: true, warning, ... }
const item = $input.first().json;

let kb = '';
if (item.content !== undefined) {
  kb = (item.content || '').trim();
} else if (item.kb_missing) {
  // Explicit empty KB; surface warning in n8n execution output for debugging
  kb = '';
}

return [{ json: {
  call_inbound: { dynamic_variables: { knowledge_base: kb } },
  _debug: { kb_len: kb.length, kb_missing: item.kb_missing || false, warning: item.warning || null }
} }];
"""

# Respond returns only `call_inbound`, stripping _debug
RESPOND_CODE = r"""
// Strip debug fields from final webhook response.
const item = $input.first().json;
return [{ json: { call_inbound: item.call_inbound } }];
"""

# Fetch current
with urllib.request.urlopen(urllib.request.Request(
    f"{BASE}/workflows/{WF_ID}", headers={"X-N8N-API-KEY": API_KEY}
